func (l *lexer) finalizeHeredoc(val []rune, marker string) ([]rune, error) {
	// convert the runes to a string, so that the indexes returned by
	// the strings package below are compatible with the slices we take
	strVal := string(val)

	// find the last newline of the heredoc, which is where the contents end
	lastNewline := strings.LastIndex(strVal, "\n")

	// collapse the content, then split into separate lines
	lines := strings.Split(strVal[:lastNewline+1], "\n")

	// figure out how much whitespace we need to strip from the front of every line
	// by getting the string that precedes the marker, on the last line
	paddingToStrip := strVal[lastNewline+1 : len(strVal)-len(marker)]

	// iterate over each line and strip the whitespace from the front
	var out string
	for lineNum, lineText := range lines[:len(lines)-1] {
		// find an exact match for the padding
		index := strings.Index(lineText, paddingToStrip)

		// if the padding doesn't match exactly at the start then we can't safely strip
		if index != 0 {
			return nil, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", marker, l.line+lineNum+1, lineText, paddingToStrip)
		}

		// strip the whitespace from the line, and remove all "\r" because Windows
		out += strings.ReplaceAll(lineText[len(paddingToStrip):], "\r", "")

		// add the newline back for every line except the last one, since
		// the newline before the marker is not part of the heredoc contents
		if lineNum != len(lines)-2 {
			out += "\n"
		}
	}

	// return the final value
	return []rune(out), nil
}

